#  Footer - custom

library(ggplot2)
library(tidyverse)

# Initialise a colourblind-friendly palette:


cbPalette2 <- c("#999999", "#E69F00", "#56B4E9", "#009E73",
                "#D55E00", "#CC79A7")


samp_vect = c(# This vector NEEDS to be in the same order as the OpenChrom
  # output, so  always copy-paste it from the original output file.
  '600 uM BG-PEG-NH2',
  '50 uM BG-PEG-NH2',
  '5 uM BG-PEG-NH2',
  '0.5 uM BG-PEG-NH2',
  '500 uM BG-PEG-MA'
)


# Firstly, convert the ValueLists into tibbles, with the index (i.e. data 
# series) declared in a dedicated column:

xListsToTibble <- function(valSublist, indx) {
  as_tibble(valSublist) %>%# Convert list to tibble
    rename(`Time/ min` = 1) %>%# Renames first (and only) column to "xVal"
    mutate(Index = indx) # Creates a new column called "Index", which takes
  # the value of indx as passed to the function
}

x_tibble <- NULL
for (i in 1:length(xValueList)){
  x_tibble <- bind_rows(xListsToTibble(xValueList[[i]], i), x_tibble)
}
x_tibble


y_tibble <- NULL
for (i in 1:length(yValueList)){
  y_tibble <- as_tibble(yValueList[[i]]) %>%
    rename(`Intensity/ mAU` = 1) %>%
    bind_rows(y_tibble)
}
y_tibble

y_shift <- 50000 # Define amount (intensity/ mAU) to shift y values by - 
# this is cumulative, and the order is defined by the below vector

shift_order <- c(# This vector determines the order of samples, from lowest
  # (baseline) to highest (most shifted)
  '500 uM BG-PEG-MA',
  '0.5 uM BG-PEG-NH2',
  '5 uM BG-PEG-NH2',
  '50 uM BG-PEG-NH2',
  '600 uM BG-PEG-NH2'
)

labels_formatted <- c(
  expression(paste('600 ',mu,'M BG-PEG-NH'[2])),
  expression(paste('50 ',mu,'M BG-PEG-NH'[2])),
  expression(paste('5 ',mu,'M BG-PEG-NH'[2])),
  expression(paste('0.5 ',mu,'M BG-PEG-NH'[2])),
  expression(paste('500 ',mu,'M BG-PEG-MA'))
)  # Vector for holding formatted labels for plot. Not sure if they're tibble-safe,
# so I'll keep them out of it.


comb_tibble <- cbind(x_tibble, y_tibble) %>%# Combine x and y values
  mutate(Sample = as.factor(samp_vect[Index])) %>%# Convert index into sample name
  select(-Index) %>%# Remove index column
  rowwise() %>%
  mutate(# Shift the y values, by pattern matching with grep (to convert to 
    # the index of shift_order vector) then multiplying the index (minus 1)
    # by the value of y_shift; finally, add this shift value to the 
    # original intensity (y) value.
    `shifted_y` = (as.numeric(
      grep(
        paste(
          '^',Sample,'$', sep = ""
        ), shift_order
      )
    ) - 1)*y_shift + `Intensity/ mAU`
  ) %>%
  mutate(Sample = factor(Sample, levels = rev(shift_order))) %>% # Reorder factor 
  # levels to be the reverse of shift_order, for pretty legend purposes.
  mutate(`Intensity shifted scaled` = `shifted_y`/100000)  # Scale down y values
  # for prettier axis.

View(comb_tibble)

#options(scipen = 999)# Disable scientific notation for prettier y axis - 
# deprecated
dev.new()
ggplot(data = filter(comb_tibble, between(`Time/ min`, 5, 15)),
       mapping = aes(x = `Time/ min`,
                     y = `Intensity shifted scaled`,
                     color = Sample)) +
  geom_line(size=1) +
  scale_colour_manual(values=cbPalette2,
                      labels=labels_formatted) +
  # xlim=c(range(5, 15)),
  # ylim=c(range(0, 1500000))
  labs(title = expression(atop(paste("HPLC UV chromatograms of BG-PEG-NH"[2]," standard curve,"),
                     "and overnight click reaction with MA-NHS")), color = "Sample") +
  xlab("Elution time/ min") +
  ylab(expression(paste("Intensity at 220 nm/ mAU * ", 10^5))) +
  annotate("segment", x = 9.5, xend = 9.95, y = 3, yend = 3, size = 1.5, colour = "black", arrow = arrow(ends = "both", angle = 90, length = unit(.2,"cm"))) +
  annotate("segment", x = 10.1, xend = 11.2, y = 2.5, yend = 2.5, size = 1.5, colour = "black", arrow = arrow(ends = "both", angle = 90, length = unit(.2,"cm"))) +
  annotate("segment", x = 11.6, xend = 12, y = 3, yend = 3, size = 1.5, colour = "black", arrow = arrow(ends = "both", angle = 90, length = unit(.2,"cm"))) +
  annotate('text', x = 10, y = 3.3, label = '1', size = 10) +
  annotate('text', x = 10.6, y = 2.8, label = '2', size = 10) +
  annotate('text', x = 12.1, y = 3.3, label = '3', size = 10) +
  theme_classic() +
  theme(plot.title = element_text(size=20, hjust = 0.5),
        axis.title = element_text(size=20), legend.text = element_text(size=20),
        axis.title.x = element_text(vjust=-1),
        axis.title.y = element_text(vjust = 2),
        legend.title = element_text(size=25),
        legend.text.align = 0,
        axis.text.x = element_text(size = 20),
        axis.text.y = element_text(size = 20),
        aspect.ratio = 1/1.5)
ggsave("HPLC-data-all.png")

